import{_ as l,o as i,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2016-JUN-23 -- Ceph Tech Talks: OpenATTIC","description":"","frontmatter":{"title":"2016-JUN-23 -- Ceph Tech Talks: OpenATTIC","date":"2016-07-22T00:00:00.000Z","updated":"2016-07-23T00:00:00.000Z","tags":["Ceph","OpenATTIC","分布式存储","存储管理","RESTful API","_MONITORING_","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.md","filePath":"posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.md","lastUpdated":1780459816000}'),s={name:"posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.md"};function p(o,t,r,a,_,c){return i(),e("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2016年6月23日</p><p><strong>参会人员</strong>： Lens Scrimer（Open Attic），会议主持人</p><p><strong>会议主题</strong>： Open Attic与Ceph的集成</p><p><strong>会议内容</strong>：</p><ul><li><strong>Open Attic介绍</strong>： <ul><li>Open Attic是一个开源的存储管理平台，旨在简化企业级存储的部署和管理。</li><li>支持多种存储协议和文件系统，包括NFS、iSCSI、CIFS和ZFS等。</li><li>提供Web界面和RESTful API，方便用户进行管理和自动化。</li></ul></li><li><strong>Open Attic与Ceph的集成</strong>： <ul><li>重点开发Ceph管理功能，以满足用户对大规模存储的需求。</li><li>集成工作主要集中在以下几个方面： <ul><li><strong>Ceph集群管理</strong>： 使用Librados和LibRBD API进行集群管理，包括池、OSD和RBD的管理。</li><li><strong>集群健康和性能监控</strong>： 使用Nagios和RRDtool进行监控，并提供图形化的仪表板。</li><li><strong>自动化</strong>： 使用Saltstack进行远程节点管理，并支持自动化任务执行。</li><li><strong>用户界面</strong>： 开发新的Ceph管理仪表板，提供更直观的用户体验。</li></ul></li></ul></li><li><strong>开发计划</strong>： <ul><li>Open Attic将继续每月发布新版本，并逐步完善Ceph管理功能。</li><li>下周，Open Attic团队将与SUSE开发者一起进行Hack Week，专注于Ceph特定功能的开发。</li><li>欢迎用户反馈和建议，共同推动Open Attic的发展。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>Open Attic团队将继续开发Ceph管理功能，并定期发布新版本。</li><li>用户可以访问Open Attic官网和GitHub仓库，获取最新信息和代码。</li><li>用户可以参与Open Attic社区，提供反馈和建议。</li></ul><p><strong>关键词</strong>：</p><ul><li>Open Attic</li><li>Ceph</li><li>分布式存储</li><li>存储管理</li><li>RESTful API</li><li>Nagios</li><li>RRDtool</li><li>Saltstack</li><li>Hack Week</li></ul>',10)])])}const h=l(s,[["render",p]]);export{g as __pageData,h as default};
